<?php
namespace App\Http\Resources\Api\V1;
use Illuminate\Http\Request;
use Illuminate\Http\Resources\Json\JsonResource;
class ProfileResource extends JsonResource { public function toArray(Request $request): array { return ['id'=>$this->id,'public_name'=>$this->public_name,'phone'=>$this->phone,'avatar_url'=>$this->avatar_path ? url('storage/'.$this->avatar_path) : null,'country'=>$this->whenLoaded('country', fn()=> $this->country ? ['id'=>$this->country->id,'name'=>$this->country->name,'iso2'=>$this->country->iso2] : null),'city'=>$this->city,'region'=>$this->region,'nationality'=>$this->nationality,'professional_title'=>$this->professional_title,'category'=>$this->whenLoaded('category', fn()=> $this->category ? ['id'=>$this->category->id,'name'=>$this->category->name] : null),'bio'=>$this->bio,'education_level'=>$this->education_level,'years_experience'=>$this->years_experience,'available_for_work'=>$this->available_for_work,'is_public'=>$this->is_public,'review_status'=>$this->review_status ?? 'draft','submitted_at'=>$this->submitted_at,'reviewed_at'=>$this->reviewed_at,'review_note'=>$this->review_note,'skills'=>$this->whenLoaded('skills', fn()=> $this->skills->map(fn($s)=>['id'=>$s->id,'name'=>$s->name,'level'=>$s->pivot->level])),'languages'=>$this->whenLoaded('languages', fn()=> $this->languages->map(fn($l)=>['id'=>$l->id,'code'=>$l->code,'name'=>$l->name,'proficiency'=>$l->pivot->proficiency])),'experiences'=>$this->whenLoaded('experiences'),'updated_at'=>$this->updated_at]; } }
